+// API keys and roles. Keys live in the data as `apiKeys`; each has one role,
+// and a higher role may do everything a lower one may (docs/DATA.md).
+import { createHash, timingSafeEqual } from "node:crypto";
+import { AppError } from "../errors.js";
+
+/** Roles from least to most allowed. */
+export const ROLES = Object.freeze(["viewer", "cook", "manager"]);
+
+const digest = (text) => createHash("sha256").update(text).digest();
+
+/** The API key record for `key`; throws `unauthorized` when it is missing or unknown. */
+export function authenticate(store, key) {
+  if (typeof key !== "string" || key === "") throw new AppError("unauthorized");
+  const wanted = digest(key);
+  let found = null;
+  for (const k of store.data.apiKeys ?? []) {
+    if (typeof k.key !== "string" || k.key === "") continue;
+    if (timingSafeEqual(digest(k.key), wanted)) found ??= k;
+  }
+  if (!found) throw new AppError("unauthorized");
+  return found;
+}
+
+/** Throws `forbidden` unless `apiKey`'s role is at least `role`. */
+export function authorize(apiKey, role) {
+  const needed = ROLES.indexOf(role);
+  if (needed < 0 || ROLES.indexOf(apiKey.role) < needed) throw new AppError("forbidden", { role });
+}
